    const val = v => v.includes('/') ? v.split('/')[0] / v.split('/')[1] : +v;
    const k = q[1] === '' ? 1 : q[1] === '-' ? -1 : +q[1], m = !q[2] ? 0 : !q[3] ? 1 : q[3] === '²' ? 2 : 3, y0 = val(q[4]), a = +q[5];
