    const val = v => v.includes('/') ? v.split('/')[0] / v.split('/')[1] : +v;
    const q = fl(p.q).match(/^A and B are ([23])×\1 matrices with det A = (-?\d+) and det B = (-?\d+)\. What is det\((-?\d*)((?:[AB]ᵀ?(?:⁻¹|²|³)?)+)\)\?$/);
