      if (btns.length !== 4 || btns.some((m, i) => m[1] !== 'ABCD'[i] || m[2] || +m[3] !== i || m[4] !== 'ABCD'[i] || m[5] !== fr(r.opts[i].v) || m[6] || m[7] !== 'ABCD'[i] || m[8] !== fr(r.opts[i].v))) fail('intpick', key, 'the four numbers are not offered as they are, A to D');
