      const yt = [...svg.matchAll(/<text x="[-\d.]+" y="([-\d.]+)" font-size="9"[^>]*>([^<]+)<\/text>/g)].map(m => [+m[1] - 3, +m[2].replace('−', '-')]);
      if (xt.length < 3 || yt.length < 2 || xt[0][1] !== a - 1 || xt[xt.length - 1][1] !== b + 1) { fail('intpick', key, 'the ticks do not run from a − 1 to b + 1'); continue; }
