  if (env.toasts.join(' | ') !== '✓ All four shapes on one curve · A slip caught and fixed | ✓ Right on the first check · A cup can fall | ✓ A cap can climb') fail('shaperead', 'hunt', `the toasts are ${env.toasts.join(' | ')}`);
