  const tr = A => A[0].map((_, j) => A.map(r => r[j]));
  const same = (A, B) => A.every((r, i) => r.every((x, j) => x === B[i][j]));
  const minus = A => A.map(r => r.map(x => -x));
  const callOf = A => same(tr(A), A) ? 'S' : same(tr(A), minus(A)) ? 'K' : 'N';
