  if (env.toasts.join(' | ') !== '✓ Backwards and still climbing | ✓ Straight up | ✓ Two slopes at one point | ✓ A flat tangent') fail('paramwalk', 'hunt', `the toasts are ${env.toasts.join(' | ')}`);
