  const go = (steps) => { for (const [fn, a] of steps) {
    const M0 = S.M, f0 = S.f, t = S.t, s = S.s; S[fn](a); S.html();
    if (fn === 'go') read(`hunt ${a}`, M0, f0, a, t, s); } return [...S.done].sort().join(); };
