  const SP = '⁰¹²³⁴⁵⁶⁷⁸⁹';
  const sp = n => String(n).replace('-', '⁻').replace(/\d/g, d => SP[d]);
  const fa = n => (n < 2 ? 1 : n * fa(n - 1));
