    S.round = null; S.newRound(); S.newRound();
    if (JSON.stringify(S.round.S) === '{"k":2,"m":2,"n":1,"al":3,"be":-1,"ga":1,"de":2,"t":1}') fail('pathpick', 'repeat', 'the same hill and path are dealt twice in a row');
