  const sse = (Q, m) => { const W = work(Q), xb = W.xb[0] / W.xb[1], yb = W.yb[0] / W.yb[1];
    return Q.p.reduce((s, [x, y]) => s + (y - (yb + m * (x - xb))) ** 2, 0); };
  const bottom = (Q, m) => { const h = 1e-4; return sse(Q, m) < sse(Q, m + h) && sse(Q, m) < sse(Q, m - h); };
