        if (!ch || ch[1] !== fs || +ch[2] !== a || +ch[3] !== b || +ch[4] !== a || !near(ch[5], f(a)) || +ch[6] !== b || !near(ch[7], f(b)) || ch[8] !== ch[7] || !near(ch[9], f(a)) || +ch[10] !== b || +ch[11] !== a || !near(ch[12], m)) fail('chord', key, `the chord is worked wrong: ${got[0]}`);
