          if (m[2] !== P || t.join() !== p.join() || q.join() !== w.join()) fail('cross', key, `the ${m[1]} check uses the wrong numbers: ${dl}`);
          if (t[0] * q[0] + t[1] * q[1] + t[2] * q[2] !== num(m[9]) || num(m[9]) !== 0) fail('cross', key, `the ${m[1]} check does not come to 0: ${dl}`);
