      for (const g of W.GOALS) { if (!!g.ok(W) !== meant[g.id]) fail('cross', key, `goal ${g.id} is ${g.ok(W) ? 'met' : 'not met'}`); if (g.ok(W)) found[g.id] = found[g.id] || key; }
