      if (/Walk v from the tip/.test(got[2]) !== m) fail('arrow', key, 'the walk sentence is wrong');
      if (m && (!near(wv[0], ku) || !near(wv[1], S.v))) fail('arrow', key, 'the parts added are not k·u and v');
      const len = got.find(l => l.startsWith('‖w‖ = √('));
